00156     // utility function for checking shader compilation/linking errors.
00157     // ------------------------------------------------------------------------
00158 
00159      void Shader::checkCompileErrors(GLuint shader, std::string type)
00160     {
00161         GLint success;
00162         GLchar infoLog[1024];
00163         if (type != "PROGRAM")
00164         {
00165             glGetShaderiv(shader, GL_COMPILE_STATUS, &success);
00166             if (!success)
00167             {
00168                 glGetShaderInfoLog(shader, 1024, NULL, infoLog);
00169                 std::cout << "ERROR::SHADER_COMPILATION_ERROR of type: " << type << "\n" << infoLog << "\n -- --------------------------------------------------- -- " << std::endl;
00170             }
00171         }
00172         else
00173         {
00174             glGetProgramiv(shader, GL_LINK_STATUS, &success);
00175             if (!success)
00176             {
00177                 glGetProgramInfoLog(shader, 1024, NULL, infoLog);
00178                 std::cout << "ERROR::PROGRAM_LINKING_ERROR of type: " << type << "\n" << infoLog << "\n -- --------------------------------------------------- -- " << std::endl;
00179             }
00180         }
00181     }
00182 
