00209      ShaderU::ShaderU(char* vertexPath, char* fragmentPath) {
00210         std::string vertexCode;
00211         std::string fragmentCode;
00212         std::ifstream vShaderFile;
00213         std::ifstream fShaderFile;
00214         vShaderFile.open(vertexPath);
00215         fShaderFile.open(fragmentPath);
00216         std::stringstream vShaderStream, fShaderStream;
00217 
00218         if (vShaderFile.good() && fShaderFile.good()) {
00219             vShaderStream << vShaderFile.rdbuf();
00220             fShaderStream << fShaderFile.rdbuf();
00221             vShaderFile.close();
00222             fShaderFile.close();
00223             vertexCode = vShaderStream.str();
00224             fragmentCode = fShaderStream.str();
00225             const char* vShaderCode = vertexCode.c_str();
00226             const char* fShaderCode = fragmentCode.c_str();
00227             textcount = fShaderCode[2];
00228             unsigned int vertex, fragment;
00229             vertex = glCreateShader(GL_VERTEX_SHADER);
00230             glShaderSource(vertex, 1, &vShaderCode, NULL);
00231             glCompileShader(vertex);
00232             checkCompileErrors(vertex, "VERTEX");
00233             fragment = glCreateShader(GL_FRAGMENT_SHADER);
00234             glShaderSource(fragment, 1, &fShaderCode, NULL);
00235             glCompileShader(fragment);
00236             checkCompileErrors(fragment, "FRAGMENT");
00237             ID = glCreateProgram();
00238             glAttachShader(ID, vertex);
00239             glAttachShader(ID, fragment);
00240             glLinkProgram(ID);
00241             checkCompileErrors(ID, "PROGRAM");
00242             glDeleteShader(vertex);
00243             glDeleteShader(fragment);
00244 
00245         }
00246 
00247     }
